//! Response parser targets: properties of `tokspur-text`'s `ResponseParser` on its own ([`check`]) and the snapshot-by-snapshot comparison with `native/src/response.cpp` ([`check_differential`]).
//!
//! Input layout: a flags byte, a separator byte, six limit bytes when the flags ask for small limits, then the generated bytes, split into feeds on the separator (see [`crate::split`]). Flags: bit 0 starts in thinking mode, bit 1 derives small limits (sometimes invalid ones) from the limit bytes, bits 2-3 pick a tool manifest, bit 4 feeds once more after `finish`, and bit 5 selects token framing with literal text and escaped parameters.

#![forbid(unsafe_code)]

use tokspur_json::{Json, Kind};
use tokspur_text::response::{
    ParameterSpec, ParameterType, ResponseKind, ResponseLimits, ResponseParser, ResponseRecord,
    ResponseStatus, ToolSpec,
};

#[cfg(feature = "cpp-oracle")]
use crate::encode::require_identical;
use crate::encode::{Writer, escape};
#[cfg(feature = "cpp-oracle")]
use crate::oracle;
use crate::{json, split};

/// One parser run: manifest, initial mode, limits and the operations.
pub struct Case<'a> {
    pub tools: Vec<ToolSpec>,
    pub thinking: bool,
    pub token_framing: bool,
    pub limits: ResponseLimits,
    /// Whether `limits` are the defaults (split invariance holds then).
    pub default_limits: bool,
    pub operations: Vec<Operation<'a>>,
}

#[derive(Clone, Copy)]
pub enum Operation<'a> {
    Feed(&'a [u8]),
    Finish,
}

fn parameter(name: &str, r#type: ParameterType, required: bool) -> ParameterSpec {
    ParameterSpec::new(name, r#type, required)
}

/// The manifest of `native/tests/test_response.cpp`, optionally with every parameter required.
fn test_tools(required: bool) -> Vec<ToolSpec> {
    vec![
        ToolSpec::new(
            "edit.file",
            vec![
                parameter("path", ParameterType::RawString, true),
                parameter("patch", ParameterType::RawString, required),
                parameter("apply", ParameterType::Boolean, required),
                parameter("count", ParameterType::Number, required),
                parameter("meta", ParameterType::Object, required),
                parameter("items", ParameterType::Array, required),
                parameter("empty", ParameterType::NullValue, required),
            ],
        ),
        ToolSpec::new("ping", Vec::new()),
    ]
}

/// The tool manifests a case can use.
pub fn manifest(choice: u8) -> Vec<ToolSpec> {
    match choice & 3 {
        0 => test_tools(false),
        1 => Vec::new(),
        2 => vec![
            ToolSpec::new("ping", Vec::new()),
            ToolSpec::new(
                "Search-2.v1",
                vec![
                    parameter("query", ParameterType::RawString, true),
                    parameter("日本 🙂 =x", ParameterType::Number, false),
                    parameter("filters", ParameterType::Object, false),
                ],
            ),
        ],
        _ => test_tools(true),
    }
}

/// Small limits from six bytes; about a fifth of them are invalid, so the constructor refusals are compared too.
fn small_limits(bytes: [u8; 6]) -> ResponseLimits {
    ResponseLimits {
        bytes: 1 + usize::from(bytes[0]) * 64,
        call_bytes: 1 + usize::from(bytes[1]) * 16,
        records: 1 + usize::from(bytes[2] % 32),
        calls: 1 + usize::from(bytes[3] % 8),
        json_nodes: 1 + usize::from(bytes[4]),
        json_depth: usize::from(bytes[5] % 80),
    }
}

/// Decodes a fuzz input into a case; `None` when it is too short.
pub fn case(data: &[u8]) -> Option<Case<'_>> {
    let (&flags, rest) = data.split_first()?;
    let (&separator, mut rest) = rest.split_first()?;
    let default_limits = flags & 2 == 0;
    let limits = if default_limits {
        ResponseLimits::default()
    } else {
        let (bytes, tail) = rest.split_first_chunk::<6>()?;
        rest = tail;
        small_limits(*bytes)
    };
    let chunks = split::chunks(rest, separator);
    let mut operations: Vec<Operation<'_>> =
        chunks.iter().map(|&chunk| Operation::Feed(chunk)).collect();
    operations.push(Operation::Finish);
    if flags & 16 != 0 {
        operations.push(Operation::Feed(chunks.last().copied().unwrap_or_default()));
        operations.push(Operation::Finish);
    }
    Some(Case {
        tools: manifest(flags >> 2),
        thinking: flags & 1 != 0,
        token_framing: flags & 32 != 0,
        limits,
        default_limits,
        operations,
    })
}

fn type_code(r#type: ParameterType) -> u8 {
    match r#type {
        ParameterType::RawString => 0,
        ParameterType::Boolean => 1,
        ParameterType::Number => 2,
        ParameterType::Object => 3,
        ParameterType::Array => 4,
        ParameterType::NullValue => 5,
        ParameterType::JsonValue => 6,
    }
}

fn status_code(status: ResponseStatus) -> u8 {
    match status {
        ResponseStatus::Incomplete => 0,
        ResponseStatus::Complete => 1,
        ResponseStatus::Error => 2,
    }
}

fn kind_code(kind: ResponseKind) -> u8 {
    match kind {
        ResponseKind::Text => 0,
        ResponseKind::Thinking => 1,
        ResponseKind::Tool => 2,
    }
}

/// The case as the shim's `response_case` reads it.
pub fn encode(case: &Case<'_>) -> Vec<u8> {
    let mut out = Writer::default();
    out.len(case.tools.len());
    for tool in &case.tools {
        out.bytes(&tool.name);
        out.len(tool.parameters.len());
        for parameter in &tool.parameters {
            out.bytes(&parameter.name);
            out.u8(type_code(parameter.r#type));
            out.u8(u8::from(parameter.required));
        }
    }
    out.u8(u8::from(case.thinking));
    out.u8(u8::from(case.token_framing));
    let limits = case.limits;
    for value in [
        limits.bytes,
        limits.call_bytes,
        limits.records,
        limits.calls,
        limits.json_nodes,
        limits.json_depth,
    ] {
        out.size(value);
    }
    out.len(case.operations.len());
    for operation in &case.operations {
        match operation {
            Operation::Feed(bytes) => {
                out.u8(0);
                out.bytes(bytes);
            }
            Operation::Finish => out.u8(1),
        }
    }
    out.out
}

fn dump_or_error(out: &mut Writer, value: &Json) {
    match value.dump() {
        Ok(text) => {
            out.u8(0);
            out.bytes(&text);
        }
        Err(error) => {
            out.u8(1);
            out.bytes(error.to_string().as_bytes());
        }
    }
}

/// The shim's `snapshot`.
fn snapshot(out: &mut Writer, returned: ResponseStatus, parser: &ResponseParser) {
    out.u8(status_code(returned));
    out.u8(status_code(parser.status()));
    out.bytes(parser.error().as_bytes());
    out.size(parser.bytes_received());
    out.len(parser.records().len());
    for record in parser.records() {
        out.u8(kind_code(record.kind));
        out.bytes(&record.text);
        out.size(record.ordinal);
        out.bytes(&record.name);
        dump_or_error(out, &record.arguments);
    }
}

fn apply(parser: &mut ResponseParser, operation: Operation<'_>) -> ResponseStatus {
    match operation {
        Operation::Feed(bytes) => parser.feed(bytes),
        Operation::Finish => parser.finish(),
    }
}

/// The shim's `response_case`, from the Rust port.
pub fn outcome(case: &Case<'_>) -> Vec<u8> {
    let mut out = Writer::default();
    let mut parser = match ResponseParser::new(case.tools.clone(), case.thinking, case.limits) {
        Ok(parser) => {
            if case.token_framing {
                parser.with_token_framing()
            } else {
                parser
            }
        }
        Err(error) => {
            out.u8(b'C');
            out.bytes(error.to_string().as_bytes());
            return out.out;
        }
    };
    out.u8(b'O');
    for &operation in &case.operations {
        let status = apply(&mut parser, operation);
        snapshot(&mut out, status, &parser);
    }
    out.out
}

/// The same manifest, limits and feeds through response.cpp and the Rust port: the constructor refusal, or the returned status, sticky status, error text, byte count and every record (kind, text, ordinal, name and dumped arguments) after every operation must be identical.
#[cfg(feature = "cpp-oracle")]
pub fn check_differential(data: &[u8]) {
    let Some(case) = case(data) else {
        return;
    };
    let encoded = encode(&case);
    let cpp = oracle::response(&encoded);
    let rust = outcome(&case);
    require_identical("ResponseParser snapshots", data, &cpp, &rust);
}

/// Every message the parser records: response.cpp, plus what it rethrows from `parse_json` and the UTF-8 checks.
const MESSAGES: [&str; 42] = [
    "invalid response limits",
    "too many response tools",
    "response name length limit",
    "unsafe response name",
    "unsupported response function name",
    "duplicate tool or too many response parameters",
    "invalid or duplicate response parameter spec",
    "response schema byte limit",
    "unrepresentable response argument number",
    "invalid response UTF-8 continuation",
    "invalid response Unicode scalar",
    "invalid response UTF-8 lead",
    "NUL byte in response",
    "response record limit",
    "response call count limit",
    "response call lacks function frame",
    "response function name is incomplete",
    "unknown response tool",
    "data after response function frame",
    "invalid response parameter frame",
    "incomplete response parameter name",
    "duplicate response parameter",
    "unknown response parameter",
    "response parameter lacks template newline",
    "incomplete response parameter value",
    "reserved response marker inside parameter",
    "wrong response parameter JSON type",
    "missing required response parameter",
    "data after response terminal marker",
    "response call byte limit",
    "truncated response tool call",
    "text after response tool calls",
    "truncated response marker or UTF-8",
    "unexpected response thinking close",
    "unexpected response thinking open",
    "terminal marker inside thinking",
    "unexpected response control marker",
    "truncated response control frame",
    "input after finished response",
    "response byte limit",
    "truncated response UTF-8",
    "truncated response marker",
];

fn expected_kind(r#type: ParameterType) -> Option<Kind> {
    Some(match r#type {
        ParameterType::RawString => Kind::String,
        ParameterType::Boolean => Kind::Boolean,
        ParameterType::Number => Kind::Number,
        ParameterType::Object => Kind::Object,
        ParameterType::Array => Kind::Array,
        ParameterType::NullValue => Kind::Null,
        ParameterType::JsonValue => return None,
    })
}

/// Record invariants after any operation: coalesced text and thinking records of valid UTF-8 without NUL, and tool records only once complete, last, numbered from zero, each naming a manifest tool with exactly typed arguments that cover its required parameters.
fn check_records(parser: &ResponseParser, tools: &[ToolSpec], input: &[u8]) {
    let records = parser.records();
    let complete = parser.status() == ResponseStatus::Complete;
    let first_tool = records
        .iter()
        .position(|record| record.kind == ResponseKind::Tool)
        .unwrap_or(records.len());
    let (stream, calls) = records.split_at(first_tool);
    for (i, record) in stream.iter().enumerate() {
        assert!(
            !record.text.is_empty()
                && std::str::from_utf8(&record.text).is_ok()
                && !record.text.contains(&0)
                && record.ordinal == 0
                && record.name.is_empty()
                && record.arguments.is_null()
                && (i == 0 || stream[i - 1].kind != record.kind),
            "malformed text/thinking record {i} for {}",
            escape(input, 512)
        );
    }
    assert!(
        calls.is_empty() || complete,
        "tool records published while {:?}: {}",
        parser.status(),
        escape(input, 512)
    );
    for (ordinal, call) in calls.iter().enumerate() {
        check_call(call, ordinal, tools, input);
    }
}

fn check_call(call: &ResponseRecord, ordinal: usize, tools: &[ToolSpec], input: &[u8]) {
    let input = || escape(input, 512);
    assert!(
        call.kind == ResponseKind::Tool && call.ordinal == ordinal && call.text.is_empty(),
        "tool record {ordinal} out of order: {}",
        input()
    );
    let Some(tool) = tools.iter().find(|tool| tool.name == call.name) else {
        panic!("tool record names no manifest tool: {}", input());
    };
    let Json::Object(arguments) = &call.arguments else {
        panic!("tool arguments are not an object: {}", input());
    };
    for (i, (name, value)) in arguments.iter().enumerate() {
        let Some(spec) = tool.parameters.iter().find(|spec| &spec.name == name) else {
            panic!("tool argument is not a parameter: {}", input());
        };
        assert!(
            expected_kind(spec.r#type).is_none_or(|kind| value.kind() == kind)
                && arguments[..i].iter().all(|(earlier, _)| earlier != name),
            "tool argument type or duplicate: {}",
            input()
        );
    }
    for spec in tool.parameters.iter().filter(|spec| spec.required) {
        assert!(
            arguments.iter().any(|(name, _)| *name == spec.name),
            "required argument missing: {}",
            input()
        );
    }
}

/// What a run reached at its first `finish`.
struct Finished {
    status: ResponseStatus,
    records: Vec<ResponseRecord>,
    bytes_received: usize,
}

/// Runs `operations`, checking the stream invariants after each one: the returned status is the sticky status; an error is final, keeps its first message (a known one) and publishes no tool record; `Complete` follows only `finish`, and input after it is refused; the byte count never exceeds what was fed or the limit. Returns the state at the first `finish`.
fn run(case: &Case<'_>, operations: &[Operation<'_>], input: &[u8]) -> Finished {
    let parser = ResponseParser::new(case.tools.clone(), case.thinking, case.limits);
    let Ok(mut parser) = parser else {
        panic!("parser construction failed for {}", escape(input, 512));
    };
    if case.token_framing {
        parser = parser.with_token_framing();
    }
    let mut fed = 0;
    let mut finished = None;
    let mut first_error: Option<String> = None;
    for &operation in operations {
        let before = parser.status();
        let status = apply(&mut parser, operation);
        if let Operation::Feed(bytes) = operation {
            fed += bytes.len();
        }
        assert_eq!(status, parser.status(), "returned status is not sticky");
        match &first_error {
            Some(message) => assert!(
                status == ResponseStatus::Error && parser.error() == message,
                "error status or message changed for {}",
                escape(input, 512)
            ),
            None if status == ResponseStatus::Error => {
                let message = parser.error();
                assert!(
                    MESSAGES.contains(&message) || json::MESSAGES.contains(&message),
                    "unknown response error {message:?} for {}",
                    escape(input, 512)
                );
                first_error = Some(message.to_owned());
            }
            None => assert!(parser.error().is_empty(), "error text without error status"),
        }
        match operation {
            Operation::Feed(_) if before == ResponseStatus::Complete => assert_eq!(
                (status, parser.error()),
                (ResponseStatus::Error, "input after finished response"),
            ),
            Operation::Feed(_) => assert_ne!(status, ResponseStatus::Complete),
            Operation::Finish => {
                assert_ne!(
                    status,
                    ResponseStatus::Incomplete,
                    "finish left the parser open"
                );
                if finished.is_none() {
                    finished = Some(Finished {
                        status,
                        records: parser.records().to_vec(),
                        bytes_received: parser.bytes_received(),
                    });
                }
            }
        }
        assert!(
            parser.bytes_received() <= fed.min(case.limits.bytes),
            "byte count beyond input or limit"
        );
        check_records(&parser, &case.tools, input);
    }
    let Some(finished) = finished else {
        panic!("case without finish for {}", escape(input, 512));
    };
    finished
}

/// `ResponseParser` on arbitrary feeds. Besides the per-operation invariants of `run`, with the default limits the outcome may not depend on how the stream was split: one feed of the whole stream, and one feed per byte for short streams, must reach the same status at `finish`, and a complete response must produce identical records and byte count.
pub fn check(data: &[u8]) {
    let Some(case) = case(data) else {
        return;
    };
    if ResponseParser::new(case.tools.clone(), case.thinking, case.limits).is_err() {
        assert!(!case.default_limits, "default limits refused");
        return;
    }
    let split = run(&case, &case.operations, data);
    if !case.default_limits {
        return;
    }
    let mut stream = Vec::new();
    for operation in &case.operations {
        match operation {
            Operation::Feed(bytes) => stream.extend_from_slice(bytes),
            Operation::Finish => break,
        }
    }
    let whole = [Operation::Feed(&stream), Operation::Finish];
    let mut alternatives = vec![run(&case, &whole, data)];
    if stream.len() <= 2048 {
        let mut bytewise: Vec<Operation<'_>> = stream.chunks(1).map(Operation::Feed).collect();
        bytewise.push(Operation::Finish);
        alternatives.push(run(&case, &bytewise, data));
    }
    for other in alternatives {
        assert_eq!(
            split.status,
            other.status,
            "status depends on the split: {}",
            escape(data, 512)
        );
        if split.status == ResponseStatus::Complete {
            assert!(
                split.records == other.records && split.bytes_received == other.bytes_received,
                "records depend on the split: {}",
                escape(data, 512)
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn input(flags: u8, separator: u8, stream: &[u8]) -> Vec<u8> {
        let mut data = vec![flags, separator];
        data.extend_from_slice(stream);
        data
    }

    const STREAMS: [&[u8]; 13] = [
        b"I considered <tool_call>x</tool_call>.</think>\n\nEditing \xe6\x97\xa5\n<tool_call>\n<function=ping>\n</function>\n</tool_call><|im_end|>\n",
        b"<tool_call><function=edit.file>\n<parameter=path>\ntrue\n</parameter>\n<parameter=count>\n-2.5e2\n</parameter>\n<parameter=meta>\n{\"a\":[1,true,null]}\n</parameter>\n</function></tool_call>",
        b"<tool_call><function=edit.file><parameter=path>\nx\n</parameter><parameter=meta>\n{\"x\":1e999}\n</parameter></function></tool_call>",
        b"answer<|im_end|>suffix",
        b"<think>unclosed",
        b"text <thi|nk> more",
        b"\xe6|\x97|\xa5 split UTF-8",
        b"```xml\n<tool_call><function=ping></function></tool_call>\n```\n<tool_call><function=ping></function></tool_call>",
        b"\"<tool_call><function=ping></function></tool_call>\"",
        b"    <tool_call><function=ping></function></tool_call>\nDone.",
        b"> <tool_call><function=ping></function></tool_call>\nDone.",
        b"<tool_call><function=edit.file><parameter=path>\n&lt;/parameter&gt; &amp;lt;\n</parameter></function></tool_call>",
        b"",
    ];

    #[test]
    fn properties_hold_for_the_response_test_streams() {
        for stream in STREAMS {
            for flags in [0, 1, 4, 8, 12, 16, 17, 32, 33, 36, 40, 44, 48, 49] {
                check(&input(flags, b'|', stream));
            }
        }
    }

    #[cfg(feature = "cpp-oracle")]
    #[test]
    fn the_cpp_parser_agrees_on_the_response_test_streams() {
        for stream in STREAMS {
            for flags in [0, 1, 4, 8, 12, 16, 17, 32, 33, 36, 40, 44, 48, 49] {
                check_differential(&input(flags, b'|', stream));
            }
            let mut small = input(2, b'|', &[]);
            small.extend_from_slice(&[0, 3, 1, 1, 2, 2]);
            small.extend_from_slice(stream);
            check(&small);
            check_differential(&small);
        }
    }

    #[test]
    fn cases_decode_flags_limits_and_feeds() {
        let data = input(2 | 16, b'|', &[1, 2, 3, 4, 5, 70, b'a', b'|', b'b']);
        let decoded = case(&data).unwrap();
        assert!(!decoded.default_limits && !decoded.thinking);
        assert_eq!(decoded.limits.bytes, 65);
        assert_eq!(decoded.limits.json_depth, 70);
        assert_eq!(decoded.operations.len(), 5);
        assert!(case(&[0]).is_none());
    }
}
